<template><div><PageHeader title="Team" description="Invite staff and manage organization access."><template #actions><button class="btn primary" @click="open=true">+ Invite member</button></template></PageHeader><div class="card"><DataTable :headers="['Member','Role','Status','Last active','']" :actions="true"><tr v-for="member in team" :key="member.email"><td><div class="row-person"><Avatar :name="member.name" size="sm"/><div><strong>{{member.name}}</strong><span>{{member.email}}</span></div></div></td><td><span class="chip">{{member.role}}</span></td><td><StatusBadge :status="member.status"/></td><td>{{member.last}}</td><td><button class="btn secondary small">Manage</button></td></tr></DataTable></div><div class="card" style="margin-top:18px"><div class="card-header"><h3>Role permissions</h3><span class="section-note">Server-side authorization required in Laravel</span></div><div class="card-pad"><div class="role-grid"><div v-for="role in roles" :key="role.name" class="info-box"><strong>{{role.name}}</strong><p class="section-note">{{role.description}}</p><div v-for="p in role.permissions" :key="p" class="perm"><span>{{p}}</span><b>✓</b></div></div></div></div></div><Modal :open="open" title="Invite team member" description="Send an organization invitation" @close="open=false"><form class="auth-form" @submit.prevent="invite"><div class="field"><label>Name</label><input class="input" v-model="form.name"></div><div class="field"><label>Email</label><input class="input" v-model="form.email" type="email"></div><div class="field"><label>Role</label><select class="select" v-model="form.role"><option>Admin</option><option>Manager</option><option>Trainer</option></select></div><button class="btn primary">Send invitation</button></form></Modal></div></template>
<script setup lang="ts">import {reactive,ref} from 'vue';import PageHeader from '../components/PageHeader.vue';import DataTable from '../components/DataTable.vue';import Avatar from '../components/Avatar.vue';import StatusBadge from '../components/StatusBadge.vue';import Modal from '../components/Modal.vue';import {useToast} from '../composables/useToast';const open=ref(false),form=reactive({name:'',email:'',role:'Trainer'});const {push}=useToast();const team=[{name:'Nibras',email:'nibras@trainingos.demo',role:'Owner',status:'active',last:'Now'},{name:'Ahmed Khan',email:'ahmed@trainingos.demo',role:'Trainer',status:'active',last:'12 min ago'},{name:'Mariam Ali',email:'mariam@trainingos.demo',role:'Trainer',status:'active',last:'1 hr ago'},{name:'Operations Desk',email:'ops@trainingos.demo',role:'Admin',status:'active',last:'Yesterday'}];const roles=[{name:'Owner',description:'Full organization control.',permissions:['Organization','Billing','Team','All data']},{name:'Admin',description:'Operational administrator.',permissions:['Learners','Courses','Batches','Reports']},{name:'Manager',description:'Day-to-day training manager.',permissions:['Learners','Batches','Attendance','Reports']},{name:'Trainer',description:'Assigned training delivery.',permissions:['Assigned batches','Attendance','Assessments','Materials']}];function invite(){open.value=false;push(`Invitation sent to ${form.email || 'team member'}.`)}</script>
